package main

import (
	"encoding/base64"
	"fmt"
	"log/slog"
	"os"
	"strings"
	"time"

	"github.com/nats-io/nats.go"

	"github.com/Yankzy/usetoro/internal/config"
)

const (
	subject = "worker.inbox.email.postmark_inbound"

	// Paste the COMPLETE value of NATS_MSG.Data from your ingress JSON log here.
	// slog serializes []byte as base64, so this must be decoded before publishing.
	capturedDataBase64 = ``
)

func main() {
	logger := slog.New(
		slog.NewJSONHandler(os.Stdout, &slog.HandlerOptions{
			Level: slog.LevelInfo,
		}),
	)

	logger.Info("starting Postmark inbound NATS replay")

	if os.Getenv("NATS_URL") == "" || strings.Contains(os.Getenv("NATS_URL"), "yankz.local") {
		os.Setenv("NATS_URL", "nats://localhost:4222")
	}

	cfg, _, err := config.Load()
	if err != nil {
		logger.Error("failed to load config", "error", err)
		os.Exit(1)
	}

	nc, err := nats.Connect(
		cfg.NATS.URL,
		nats.Name("test-postmark-inbound-replay"),
		nats.Timeout(5*time.Second),
	)
	if err != nil {
		logger.Error("failed to connect to NATS", "error", err)
		os.Exit(1)
	}
	defer nc.Close()

	body, err := base64.StdEncoding.DecodeString(capturedDataBase64)
	if err != nil {
		logger.Error("failed to decode captured NATS message data", "error", err)
		os.Exit(1)
	}

	if len(body) == 0 {
		logger.Error("captured NATS message body is empty")
		os.Exit(1)
	}

	msg := nats.NewMsg(subject)
	msg.Data = body
	msg.Header.Set(
		nats.MsgIdHdr,
		fmt.Sprintf("test-postmark-replay-%d", time.Now().UnixNano()),
	)
	msg.Header.Set("Nats-TTL", "1m")

	logger.Info(
		"publishing captured Postmark inbound message",
		"subject", msg.Subject,
		"size", len(msg.Data),
		"message_id", msg.Header.Get(nats.MsgIdHdr),
	)

	if err := nc.PublishMsg(msg); err != nil {
		logger.Error(
			"failed to publish captured message",
			"subject", subject,
			"error", err,
		)
		os.Exit(1)
	}

	if err := nc.FlushTimeout(5 * time.Second); err != nil {
		logger.Error("failed to flush NATS connection", "error", err)
		os.Exit(1)
	}

	fmt.Println()
	fmt.Println("=======================================================")
	fmt.Println("  ✅ POSTMARK INBOUND MESSAGE REPLAYED")
	fmt.Printf("  Subject: %s\n", subject)
	fmt.Printf("  Bytes:   %d\n", len(body))
	fmt.Println("=======================================================")
}
